package dflow

import (
	"context"
	"encoding/json"
	"fmt"
)

// Wakeup persists a callback and its wake notification. token is generated by
// the engine and delivered with the Request notification; it is not a name
// chosen by node code. The caller/dispatcher subsequently invokes Resume.
func (e *Engine) Wakeup(ctx context.Context, nodeID, token string, response any) (bool, error) {
	if _, ok := e.graph.nodes[nodeID]; !ok || token == "" {
		return false, ErrWaitNotFound
	}
	data, err := json.Marshal(response)
	if err != nil {
		return false, err
	}
	accepted, err := e.infra.Resolve(ctx, nodeID, token, data)
	if err != nil {
		return false, &InfrastructureError{Op: "Resolve", Cause: err}
	}
	return accepted, nil
}

// Resume reads the original input and drives available nodes under the lease.
// No workflow lifecycle transition is inferred from this call's outcome.
func (e *Engine) Resume(ctx context.Context) (*State, error) {
	state, err := e.infra.Load(ctx)
	if err != nil {
		return nil, &InfrastructureError{Op: "Load", Cause: err}
	}
	if state == nil {
		return nil, fmt.Errorf("dflow: no execution to resume")
	}
	return e.Run(ctx, state.Input)
}
